using System.Collections.Generic;

// Pure logic (no UnityEngine) so it can be unit tested and, later,
// seeded deterministically for the Phase 4 daily puzzle.
public class TileDealer
{
    // Weights derived from actual jamo frequency across ALL THREE word
    // sets (24,137 words, 56,297 syllables), damped with x^0.7 so common
    // jamo lead without flooding the tray with duplicates. Consonant
    // weights count both initial (choseong) and final (jongseong)
    // occurrences, since one consonant tile serves either position.
    // Generated by Tools/gen_jamo_weights.ps1 — re-run it instead of
    // hand-editing when the word list changes.
    //
    // Nothing here is hand-set any more. The old ㅞ exception existed
    // because ㅞ never occurred in topik1; the krdict corpus has it 25
    // times, and every other jamo has a real count too.
    //
    // The absolute numbers are far larger than the previous table's only
    // because the corpus is ~27x bigger and the damping applies to raw
    // counts. Just the ratios matter.
    private static readonly (string jamo, int weight)[] ChoseongWeights =
    {
        ("ㄱ", 726), ("ㄲ", 75), ("ㄴ", 562), ("ㄷ", 386), ("ㄸ", 54),
        ("ㄹ", 505), ("ㅁ", 447), ("ㅂ", 420), ("ㅃ", 35), ("ㅅ", 524),
        ("ㅆ", 36), ("ㅇ", 804), ("ㅈ", 483), ("ㅉ", 43), ("ㅊ", 260),
        ("ㅋ", 82), ("ㅌ", 168), ("ㅍ", 191), ("ㅎ", 309)
    };

    private static readonly (string jamo, int weight)[] JungseongWeights =
    {
        ("ㅏ", 752), ("ㅐ", 261), ("ㅑ", 85), ("ㅒ", 2), ("ㅓ", 429),
        ("ㅔ", 126), ("ㅕ", 281), ("ㅖ", 62), ("ㅗ", 492), ("ㅘ", 124),
        ("ㅙ", 14), ("ㅚ", 88), ("ㅛ", 121), ("ㅜ", 463), ("ㅝ", 60),
        ("ㅞ", 10), ("ㅟ", 77), ("ㅠ", 102), ("ㅡ", 275), ("ㅢ", 48),
        ("ㅣ", 578)
    };

    // Fraction of dealt tiles that are consonants; the rest are vowels.
    // Corpus tile demand is 60.1% consonants — for the 14-tile tray both
    // ratios give the same 8/6 split, so keep the rounder number.
    private const double ConsonantRatio = 0.55;

    private readonly System.Random _random;

    public TileDealer() : this(System.Environment.TickCount) { }

    public TileDealer(int seed)
    {
        _random = new System.Random(seed);
    }

    public string NextChoseong() => WeightedPick(ChoseongWeights);

    public string NextJungseong() => WeightedPick(JungseongWeights);

    public string NextJamo() =>
        _random.NextDouble() < ConsonantRatio ? NextChoseong() : NextJungseong();

    // Exposes the dealer's RNG so tray shuffles stay deterministic under
    // a seed (Phase 4 daily puzzle).
    public int NextIndex(int maxExclusive) => _random.Next(maxExclusive);

    // Deals a balanced hand: ~55% consonants, ~45% vowels, shuffled,
    // so a full tray always contains enough vowels to build syllables.
    public List<string> Deal(int count) => DealRefill(count, 0, 0);

    // Deals `count` replacement jamo chosen so that the whole tray
    // (replacements + surviving tiles) returns to the target consonant/
    // vowel split. Per-tile coin flips would let the tray drift vowel-
    // starved under Zen, the one mode that refills on every consumed tile.
    public List<string> DealRefill(int count, int existingConsonants, int existingVowels)
    {
        int total = count + existingConsonants + existingVowels;
        int targetConsonants = (int)System.Math.Round(total * ConsonantRatio);
        int consonants = System.Math.Max(0,
            System.Math.Min(count, targetConsonants - existingConsonants));

        var result = new List<string>(count);
        for (int i = 0; i < consonants; i++)
            result.Add(NextChoseong());
        while (result.Count < count)
            result.Add(NextJungseong());

        Shuffle(result);
        return result;
    }

    private void Shuffle(List<string> list)
    {
        for (int i = list.Count - 1; i > 0; i--)
        {
            int j = _random.Next(i + 1);
            (list[i], list[j]) = (list[j], list[i]);
        }
    }

    private string WeightedPick((string jamo, int weight)[] pool)
    {
        int total = 0;
        foreach (var entry in pool)
            total += entry.weight;

        int roll = _random.Next(total);
        foreach (var entry in pool)
        {
            roll -= entry.weight;
            if (roll < 0) return entry.jamo;
        }
        return pool[pool.Length - 1].jamo;
    }
}
